PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('supervisor','driver')));
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires REAL NOT NULL);
CREATE TABLE IF NOT EXISTS zones (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, schedule TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE IF NOT EXISTS vehicles (id INTEGER PRIMARY KEY, name TEXT UNIQUE NOT NULL, available INTEGER NOT NULL DEFAULT 1 CHECK(available IN (0,1)));
CREATE TABLE IF NOT EXISTS drivers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, user_id INTEGER UNIQUE NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS routes (id INTEGER PRIMARY KEY, name TEXT NOT NULL, zone_id INTEGER NOT NULL REFERENCES zones(id), vehicle_id INTEGER NOT NULL REFERENCES vehicles(id), driver_id INTEGER NOT NULL REFERENCES drivers(id), starts REAL NOT NULL, deadline REAL NOT NULL CHECK(deadline > starts), stops INTEGER NOT NULL CHECK(stops BETWEEN 1 AND 100), started REAL, claimed REAL, verified REAL, verifier INTEGER REFERENCES users(id), interrupted INTEGER NOT NULL DEFAULT 0, demo INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS collections (id INTEGER PRIMARY KEY, route_id INTEGER NOT NULL REFERENCES routes(id), stop INTEGER NOT NULL, actor INTEGER NOT NULL REFERENCES users(id), recorded REAL NOT NULL, evidence TEXT NOT NULL, UNIQUE(route_id,stop));
CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY, route_id INTEGER NOT NULL REFERENCES routes(id), kind TEXT NOT NULL CHECK(kind IN ('delayed','missed','breakdown')), occurred REAL NOT NULL, detail TEXT NOT NULL, resolved REAL, resolution TEXT, UNIQUE(route_id,kind));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, route_id INTEGER REFERENCES routes(id), actor INTEGER REFERENCES users(id), kind TEXT NOT NULL, occurred REAL NOT NULL, detail TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS incident_time ON incidents(occurred,kind);
CREATE INDEX IF NOT EXISTS route_schedule ON routes(starts,deadline);
CREATE INDEX IF NOT EXISTS route_events ON events(route_id,id);
PRAGMA user_version = 1;
